  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-border: #263554;
      --text: #f4f7fb;
      --muted: #aebbd0;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --error: #fca5a5;
      --error-bg: rgba(252, 165, 165, 0.12);
      --input: #0f172a;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.18), transparent 32rem),
        linear-gradient(135deg, #070b16 0%, var(--bg) 60%, #111827 100%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 34rem);
    }

    .support-card {
      padding: 2rem;
      border: 1px solid var(--panel-border);
      border-radius: 1.25rem;
      background: rgba(18, 26, 47, 0.94);
      box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.4);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.8rem, 5vw, 2.5rem);
      line-height: 1.15;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--muted);
    }

    .form-field {
      margin-bottom: 1.25rem;
    }

    label {
      display: block;
      margin-bottom: 0.45rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 0.85rem 1rem;
      border: 1px solid #3a4a68;
      border-radius: 0.75rem;
      background: var(--input);
      color: var(--text);
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease;
    }

    input::placeholder {
      color: #75839a;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 0.2rem rgba(125, 211, 252, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      background: linear-gradient(var(--error-bg), var(--error-bg)), var(--input);
    }

    .helper-text,
    .error-message {
      display: block;
      margin-top: 0.4rem;
      font-size: 0.9rem;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.35em;
      color: var(--error);
      font-weight: 700;
    }

    button {
      width: 100%;
      padding: 0.95rem 1.2rem;
      border: 0;
      border-radius: 0.85rem;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #07111f;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 0.8rem 1.8rem rgba(56, 189, 248, 0.22);
    }

    button:focus {
      outline: 3px solid rgba(244, 247, 251, 0.85);
      outline-offset: 3px;
    }

    .success-message {
      margin: 1rem 0 0;
      color: #bbf7d0;
      font-weight: 700;
    }
  </style>
</head>
<body>
  <main>
    <section class="support-card" aria-labelledby="support-title">
      <h1 id="support-title">Contact support</h1>
      <p class="intro">Tell us how to reach you, and our support team will follow up.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            aria-describedby="full-name-error"
            aria-invalid="false"
            required
          >
          <span class="error-message" id="full-name-error" aria-live="polite"></span>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            aria-describedby="email-error"
            aria-invalid="false"
            required
          >
          <span class="error-message" id="email-error" aria-live="polite"></span>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            placeholder="+1 555 123 4567"
            aria-describedby="phone-help phone-error"
            aria-invalid="false"
          >
          <span class="helper-text" id="phone-help">Optional. Use digits, spaces, dashes, parentheses, or a leading plus sign, such as +1 555 123 4567.</span>
          <span class="error-message" id="phone-error" aria-live="polite"></span>
        </div>

        <button type="submit">Submit request</button>
        <p class="success-message" id="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const successMessage = document.querySelector("#success-message");

    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Full name is required.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmed = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmed) {
            return "Email address is required.";
          }

          return emailPattern.test(trimmed) ? "" : "Enter a valid email address.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmed = value.trim();
          const phonePattern = /^\+?[0-9\s\-()]{7,20}$/;

          if (!trimmed) {
            return "";
          }

          return phonePattern.test(trimmed) ? "" : "Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign.";
        }
      }
    };

    function showError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      showError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        validateField(field);
        successMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.values(fields).every(validateField);

      if (!isValid) {
        successMessage.textContent = "";
        const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute("aria-invalid") === "true");
        firstInvalid.input.focus();
        return;
      }

      successMessage.textContent = "Thanks. Your support request is ready to send.";
      form.reset();
      Object.values(fields).forEach((field) => showError(field, ""));
    });
  </script>
</body>
</html>
